 where o.order_no = m.order_no
   and coalesce(o.doc_no,'') = ''
   and not exists (select 1 from orders o2 where o2.doc_no = m.doc_no);

-- สรุปหลังรัน: จำนวนออเดอร์ที่มีเลขใบเบิก แยกแพลตฟอร์ม
select platform,
       count(*) filter (where coalesce(doc_no,'') <> '') as มีเลขใบเบิก,
       count(*) as ทั้งหมด
  from orders where deleted_at is null group by 1 order by 2 desc;

